-- Central e gatilhos de notificações executados no SQL Editor.
create table if not exists public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,notification_type text not null check(notification_type in ('message','offer_received','offer_accepted','offer_rejected','counteroffer','order_created','order_updated','shipment','delivery','cancellation','issue')),title text not null check(char_length(title) between 1 and 120),body text not null check(char_length(body) between 1 and 300),link text,read_at timestamptz,created_at timestamptz not null default now());
create index if not exists notifications_user_created_idx on public.notifications(user_id,created_at desc);create index if not exists notifications_unread_idx on public.notifications(user_id,read_at) where read_at is null;alter table public.notifications enable row level security;
create policy "Usuário visualiza suas notificações" on public.notifications for select using(auth.uid()=user_id);create policy "Usuário marca suas notificações como lidas" on public.notifications for update using(auth.uid()=user_id) with check(auth.uid()=user_id);grant select on public.notifications to authenticated;grant update(read_at) on public.notifications to authenticated;
-- As funções de notificação de mensagens, propostas e pedidos estão registradas no SQL aplicado no painel do projeto.
